BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(13);
CREATE FUNCTION pg_temp.fid(text) RETURNS uuid LANGUAGE sql IMMUTABLE AS 'SELECT md5($1)::uuid';
INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) VALUES(pg_temp.fid('officer'),'authenticated','authenticated','release-benchmark@local.test',now(),'{}','{}');
INSERT INTO public.organizations(id,name,username,type,join_code) VALUES(pg_temp.fid('org'),'Release benchmark','release-benchmark','school','990821');
INSERT INTO public.organization_members(organization_id,user_id,role,status) VALUES(pg_temp.fid('org'),pg_temp.fid('officer'),'admin','active');
INSERT INTO plugin_data.csf_terms(id,organization_id,code,label,school_year,semester,is_current,application_review_source) VALUES(pg_temp.fid('term'),pg_temp.fid('org'),'F30','Fall 2030','2030-2031','fall',true,'sheet');
INSERT INTO plugin_data.csf_cohorts(id,organization_id,graduation_year,label) SELECT pg_temp.fid('cohort'||n),pg_temp.fid('org'),2031+n,'Class fixture '||n FROM generate_series(1,4)n;
INSERT INTO plugin_data.csf_cohort_terms(organization_id,cohort_id,term_id) SELECT pg_temp.fid('org'),pg_temp.fid('cohort'||n),pg_temp.fid('term') FROM generate_series(1,4)n;
INSERT INTO plugin_data.csf_profiles(id,organization_id,first_name,last_name,normalized_first_name,normalized_last_name) SELECT pg_temp.fid('profile'||n),pg_temp.fid('org'),'Fictional'||n,'Applicant','fictional'||n,'applicant' FROM generate_series(1,622)n;
INSERT INTO plugin_data.csf_profile_cohort_memberships(organization_id,profile_id,cohort_id) SELECT pg_temp.fid('org'),pg_temp.fid('profile'||n),pg_temp.fid('cohort'||(1+n%4)) FROM generate_series(1,622)n;
INSERT INTO plugin_data.csf_term_applications(id,organization_id,profile_id,cohort_id,term_id,source,status) SELECT pg_temp.fid('app'||n),pg_temp.fid('org'),pg_temp.fid('profile'||n),pg_temp.fid('cohort'||(1+n%4)),pg_temp.fid('term'),'manual','submitted' FROM generate_series(1,622)n;
INSERT INTO plugin_data.csf_sheet_sources(id,organization_id,title,provider,source_type,drive_file_id,spreadsheet_id) VALUES(pg_temp.fid('source'),pg_temp.fid('org'),'Fictional responses','google_sheets','application_responses','fictional-responses','fictional-responses');
INSERT INTO plugin_data.csf_application_decision_mappings(organization_id,source_id,decision_columns,reason_columns) VALUES(pg_temp.fid('org'),pg_temp.fid('source'),ARRAY[7],ARRAY[]::integer[]);
INSERT INTO plugin_data.csf_application_decision_sync_runs(id,organization_id,term_id,actor_user_id,request_id,request_fingerprint,status) VALUES(pg_temp.fid('sync'),pg_temp.fid('org'),pg_temp.fid('term'),pg_temp.fid('officer'),pg_temp.fid('sync-request'),'fixture','completed');
INSERT INTO plugin_data.csf_application_decision_sync_sources(organization_id,run_id,source_id,read_status,spreadsheet_file_id,provider_version,sheet_tab_name,requested_range,content_hash,mapping_version) VALUES(pg_temp.fid('org'),pg_temp.fid('sync'),pg_temp.fid('source'),'read','fictional-responses','1','Responses','A1:H623','fixture','1');
INSERT INTO plugin_data.csf_application_decision_stages(organization_id,application_id,term_id,profile_id,source_id,staged_decision,block_reason,last_sync_run_id) SELECT pg_temp.fid('org'),pg_temp.fid('app'||n),pg_temp.fid('term'),pg_temp.fid('profile'||n),pg_temp.fid('source'),CASE WHEN n<=580 THEN 'accepted' WHEN n<=600 THEN 'rejected' WHEN n<=620 THEN 'on_hold' ELSE 'conflict' END,CASE WHEN n BETWEEN 601 AND 620 THEN 'awaiting_review' WHEN n=621 THEN 'mixed_colors' ELSE NULL END,pg_temp.fid('sync') FROM generate_series(1,621)n;
INSERT INTO plugin_data.csf_sheet_sync_destinations(id,organization_id,spreadsheet_file_id,sheet_id,kind,cohort_id,term_id,is_test,configured_by,enabled,privacy_verified_at,comment_capability,discussion_transport) SELECT pg_temp.fid('destination'||n),pg_temp.fid('org'),'fictional-export-'||n,0,CASE WHEN n=0 THEN 'applications' ELSE 'class' END,CASE WHEN n=0 THEN NULL ELSE pg_temp.fid('cohort'||n) END,pg_temp.fid('term'),true,pg_temp.fid('officer'),true,now(),'available','none' FROM generate_series(0,4)n;

CREATE TEMP TABLE release_result(receipt jsonb);
CREATE TEMP TABLE reviewed_token AS SELECT encode(extensions.digest(convert_to(string_agg(application_id::text||'|'||staged_decision||'|'||coalesce(block_reason,'')||'|'||release_state||'|'||last_sync_run_id::text,E'\n' ORDER BY application_id),'UTF8'),'sha256'),'hex') token FROM plugin_data.csf_application_decision_stages WHERE organization_id=pg_temp.fid('org');
SELECT extensions.ok(NOT has_function_privilege('anon','plugin_data.csf_queue_sheet_sync_snapshot_internal(uuid,uuid,text,uuid,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','plugin_data.csf_queue_sheet_sync_snapshot_internal(uuid,uuid,text,uuid,jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','plugin_data.csf_queue_sheet_sync_snapshot_internal(uuid,uuid,text,uuid,jsonb)','EXECUTE'),'precomputed export snapshots stay owner-only');
SELECT extensions.throws_ok($$SELECT plugin_data.csf_release_reviewed_sheet_decisions(pg_temp.fid('org'),pg_temp.fid('officer'),pg_temp.fid('term'),pg_temp.fid('release'),repeat('0',64))$$,'23514','Decisions changed. Review the release again.','a stale preview publishes nothing');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_term_memberships WHERE organization_id=pg_temp.fid('org')),0::bigint,'stale review creates no memberships');
INSERT INTO release_result SELECT plugin_data.csf_release_reviewed_sheet_decisions(pg_temp.fid('org'),pg_temp.fid('officer'),pg_temp.fid('term'),pg_temp.fid('release'),(SELECT token FROM reviewed_token));
SET CONSTRAINTS ALL IMMEDIATE;
SELECT extensions.is((SELECT receipt->>'released' FROM release_result),'600','one reviewed release publishes all 600 ready decisions with exports enabled');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_term_applications WHERE organization_id=pg_temp.fid('org') AND decision_status='approved'),580::bigint,'accountless accepted decisions remain attached to profiles');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_term_applications WHERE organization_id=pg_temp.fid('org') AND decision_status='rejected'),20::bigint,'red rows publish as rejected');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_term_applications WHERE organization_id=pg_temp.fid('org') AND decision_status='pending'),22::bigint,'holds, a conflict and an unstaged application remain pending');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_term_memberships WHERE organization_id=pg_temp.fid('org') AND status='accepted'),580::bigint,'every acceptance has exactly one semester membership');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_sheet_sync_bindings WHERE organization_id=pg_temp.fid('org')),1200::bigint,'only the application and its own class receive bindings');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_sheet_sync_bindings b JOIN plugin_data.csf_sheet_sync_destinations d ON d.id=b.destination_id WHERE b.organization_id=pg_temp.fid('org') AND d.kind='class' AND NOT EXISTS(SELECT 1 FROM plugin_data.csf_profile_cohort_memberships m WHERE m.organization_id=b.organization_id AND m.profile_id=b.record_id AND m.cohort_id=d.cohort_id AND m.status='active')),0::bigint,'class export bindings never include another class');
CREATE TEMP TABLE before_replay AS SELECT count(*) n FROM plugin_data.csf_sheet_writeback_ledger WHERE organization_id=pg_temp.fid('org');
SELECT extensions.is(plugin_data.csf_release_reviewed_sheet_decisions(pg_temp.fid('org'),pg_temp.fid('officer'),pg_temp.fid('term'),pg_temp.fid('release'),(SELECT token FROM reviewed_token))->>'replay','true','the same reviewed release returns its durable receipt');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_sheet_writeback_ledger WHERE organization_id=pg_temp.fid('org')),(SELECT n FROM before_replay),'a release retry does not duplicate exports');
SELECT extensions.is((SELECT count(*) FROM plugin_data.csf_application_decision_releases WHERE organization_id=pg_temp.fid('org')),1::bigint,'a retry keeps one term release');
SELECT * FROM extensions.finish();
ROLLBACK;
